CREATE TYPE "Role" AS ENUM ('ADMIN','SALES');
CREATE TYPE "LeadStatus" AS ENUM ('NEW','PROSPECT','WON','LOST');
CREATE TYPE "ActivityType" AS ENUM ('NOTE','CALL','WHATSAPP','MEETING');
CREATE TYPE "FollowUpStatus" AS ENUM ('PENDING','DONE','CANCELLED');
CREATE TABLE "User" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'SALES',"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Lead" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"phone" TEXT NOT NULL,"email" TEXT,"source" TEXT,"product" TEXT,"estimatedValue" DECIMAL(15,2) NOT NULL DEFAULT 0,"closedValue" DECIMAL(15,2),"status" "LeadStatus" NOT NULL DEFAULT 'NEW',"lostReason" TEXT,"closedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"assignedToId" UUID NOT NULL,"createdById" UUID NOT NULL,CONSTRAINT "Lead_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Lead_assignedToId_status_idx" ON "Lead"("assignedToId","status");
CREATE INDEX "Lead_createdAt_idx" ON "Lead"("createdAt");
CREATE TABLE "Activity" ("id" UUID NOT NULL,"leadId" UUID NOT NULL,"userId" UUID NOT NULL,"type" "ActivityType" NOT NULL DEFAULT 'NOTE',"notes" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Activity_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Activity_leadId_createdAt_idx" ON "Activity"("leadId","createdAt");
CREATE TABLE "FollowUp" ("id" UUID NOT NULL,"leadId" UUID NOT NULL,"userId" UUID NOT NULL,"dueAt" TIMESTAMP(3) NOT NULL,"notes" TEXT,"status" "FollowUpStatus" NOT NULL DEFAULT 'PENDING',"completedAt" TIMESTAMP(3),CONSTRAINT "FollowUp_pkey" PRIMARY KEY ("id"));
CREATE INDEX "FollowUp_userId_dueAt_idx" ON "FollowUp"("userId","dueAt");
CREATE TABLE "StatusHistory" ("id" UUID NOT NULL,"leadId" UUID NOT NULL,"userId" UUID NOT NULL,"oldStatus" "LeadStatus" NOT NULL,"newStatus" "LeadStatus" NOT NULL,"changedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "StatusHistory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiAnalysis" ("id" UUID NOT NULL,"userId" UUID NOT NULL,"question" TEXT NOT NULL,"response" TEXT NOT NULL,"scope" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AiAnalysis_pkey" PRIMARY KEY ("id"));
ALTER TABLE "Lead" ADD CONSTRAINT "Lead_assignedToId_fkey" FOREIGN KEY ("assignedToId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Lead" ADD CONSTRAINT "Lead_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Activity" ADD CONSTRAINT "Activity_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "Lead"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Activity" ADD CONSTRAINT "Activity_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "FollowUp" ADD CONSTRAINT "FollowUp_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "Lead"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "FollowUp" ADD CONSTRAINT "FollowUp_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "StatusHistory" ADD CONSTRAINT "StatusHistory_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "Lead"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "StatusHistory" ADD CONSTRAINT "StatusHistory_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "AiAnalysis" ADD CONSTRAINT "AiAnalysis_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
